ummary><p>{{t('faqAddBody')}}</p></details><details><summary>{{t('faqNotes')}}</summary><p>{{t('faqNotesBody')}}</p></details></div></section><section v-else-if="path==='/categories'" class="public-listing"><div class="public-title-row"><div><span class="public-kicker muted">{{t('collectionsKicker')}}</span><h1>Collections</h1><p>{{t('collectionsIntro')}}</p></div></div><div class="public-collections"><button v-for="c in categories" :key="c.id" class="public-collection" @click="navigate('/duas')"><span>{{c.icon||'✦'}}</span><div><b>{{c.name}}</b><small>{{c.duas_count||0}} duas</small></div><ArrowUpRight/></button></div></section>
<section v-else-if="path==='/notes'" class="public-listing"><div class="public-title-row"><div><span class="public-kicker muted">{{t('notesKicker')}}</span><h1>{{t('notesTitle')}}</h1><p>{{t('notesIntro')}}</p></div></div><div v-if="notes.length" class="public-notes-grid"><article v-for="n in notes" :key="n.id" class="public-note"><span class="public-note-date">{{new Date(n.created_at).toLocaleDateString('en',{month:'long',day:'numeric',year:'numeric'})}}</span><h3>{{n.title}}</h3><p>{{n.body}}</p></article></div><div v-else class="public-empty">{{t('emptyNotes')}}</div></section><section v-else-if="path==='/stories'" class="public-listing"><div class="public-title-row"><div><span class="public-kicker muted">{{language==='bn'?'জীবন থেকে শিক্ষা':'BIOGRAPHIES · CONTEXT · LESSONS'}}</span><h1>{{language==='bn'?'ইসলামের গল্প':'Stories of Islam'}}</h1><p>{{language==='bn'?'নবী, সাহাবি, তাবেঈন, আলেম ও ইসলামের নারীদের জীবনকথা।':'Life journeys and lessons from prophets, companions, early generations, scholars and women of Islam.'}}</p></div><label class="public-search"><Search :size="17"/><input v-model="search" :placeholder="language==='bn'?'নাম বা গল্প খুঁজুন':'Search names and stories'"/></label></div><div class="story-filter-row"><button :class="{active:!storyTypeFilter}" @click="navigate('/stories')">{{language==='bn'?'সব গল্প':'All stories'}}</button><button v-for="item in storyGroups" :key="item.type" :class="{active:storyTypeFilter===item.type||(storyTypeFilter==='women'&&item.type==='women')}" @click="navigate('/stories?type='+item.type)">{{language==='bn'?item.bn:item.en}}</button></div><div v-if="filteredStories.length" class="content-card-grid"><article v-for="story in filteredStories" :key="story.id" class="content-card"><div class="content-card-cover" :style="story.cover_url?{backgroundImage:`linear-gradient(180deg,#193f3a05,#193f3ab0),url(${story.cover_url})`}:{}"><span>{{typeName(story.story_type)}}</span></div><div class="content-card-body"><small>{{story.person_name||story.era_label}}</small><h3>{{story.title}}</h3><p>{{story.short_story||story.reason}}</p><button class="public-more" @click="navigate('/stories/'+story.slug)">{{language==='bn'?'পূর্ণ গল্প পড়ুন':'Read the story'}} <ArrowUpRight :size="14"/></button></div></article></div><div v-else class="public-empty"><b>{{language==='bn'?'এখনও গল্প প্রকাশিত হয়নি':'No stories published yet'}}</b><p>{{language==='bn'?'অ্যাডমিন জীবনী যোগ ও প্রকাশ করলে এখানে দেখা যাবে।':'Published biographies will appear here with their sources and lessons.'}}</p></div></section>
<section v-else-if="path.startsWith('/stories/')" class="public-listing detail-page"><div v-if="publicDetail" class="long-content"><button class="back-link" @click="navigate('/stories')">← {{language==='bn'?'সব গল্প':'All stories'}}</button><div class="detail-hero" :style="publicDetail.cover_url?{backgroundImage:`linear-gradient(180deg,#193f3a0a,#193f3ab8),url(${publicDetail.cover_url})`}:{}"><span>{{typeName(publicDetail.story_type)}}<template v-if="publicDetail.era_label"> · {{publicDetail.era_label}}</template></span><h1>{{publicDetail.title}}</h1><p v-if="publicDetail.person_name">{{publicDetail.person_name}}</p></div><div class="detail-body"><section v-if="publicDetail.short_story"><h2>{{language==='bn'?'সংক্ষিপ্ত পরিচিতি':'At a glance'}}</h2><p>{{publicDetail.short_story}}</p></section><section v-if="publicDetail.reason"><h2>{{language==='bn'?'প্রেক্ষাপট ও তাৎপর্য':'Context and significance'}}</h2><p>{{publicDetail.reason}}</p></section><section v-if="publicDetail.life_journey"><h2>{{language==='bn'?'জীবনযাত্রা':'Life journey'}}</h2><p>{{publicDetail.life_journey}}</p></section><section v-if="publicDetail.full_story"><h2>{{language==='bn'?'পূর্ণ কাহিনি':'Full story'}}</h2><p>{{publicDetail.full_story}}</p></section><section v-if="publicDetail.lessons"><h2>{{language==='bn'?'শিক্ষা ও ভাবনা':'Lessons and reflections'}}</h2><p>{{publicDetail.lessons}}</p></section><section v-if="publicDetail.sources?.length"><h2>{{language==='bn'?'সূত্র ও আরও পড়ুন':'Sources and further reading'}}</h2><a v-for="(source,i) in publicDetail.sources" :key="source" class="source-row" :href="source" target="_blank" rel="noopener">{{language==='bn'?'সূত্র':'Source'}} {{i+1}} <ArrowUpRight :size="14"/></a></section><aside class="source-disclaimer">{{language==='bn'?'ধর্মীয় ইতিহাস ও বর্ণনা নির্ভরযোগ্য সূত্র থেকে যাচাই করুন।':'Historical and religious accounts should be checked against reliable sources.'}}</aside></div></div><div v-else class="public-empty">{{language==='bn'?'কাহিনি লোড হচ্ছে…':'Loading story…'}}</div></section>
<section v-else-if="path==='/masael'" class="public-listing"><div class="public-title-row"><div><span class="public-kicker muted">{{language==='bn'?'দৈনন্দিন জীবনের প্রশ্ন':'QUESTIONS · ANSWERS · REFERENCES'}}</span><h1>{{language==='bn'?'মাসায়েল':'Masael'}}</h1><p>{{language==='bn'?'প্রশ্ন, সংক্ষিপ্ত উত্তর ও সূত্রভিত্তিক ব্যাখ্যা।':'Practical questions with concise answers and references curated by the administrator.'}}</p></div><label class="public-search"><Search :size="17"/><input v-model="search" :placeholder="language==='bn'?'প্রশ্ন খুঁজুন':'Search questions'"/></label></div><div v-if="filteredMasail.length" class="masael-list"><article v-for="item in filteredMasail" :key="item.id" class="masael-card"><span class="public-tag">{{item.category|| (language==='bn'?'মাসায়েল':'Masael')}}</span><h3>{{item.title}}</h3><p class="masael-question">{{item.question}}</p><p>{{item.short_answer}}</p><button class="public-more" @click="navigate('/masael/'+item.slug)">{{language==='bn'?'বিস্তারিত ও সূত্র':'Full answer and sources'}} <ArrowUpRight :size="14"/></button></article></div><div v-else class="public-empty"><b>{{language==='bn'?'এখনও কোনো মাসআলা প্রকাশিত হয়নি':'No published questions yet'}}</b><p>{{language==='bn'?'অ্যাডমিন উত্তর ও সূত্র যোগ করলে এখানে দেখা যাবে।':'Published answers and references will appear here.'}}</p></div></section>
<section v-else-if="path.startsWith('/masael/')" class="public-listing detail-page"><div v-if="publicDetail" class="long-content"><button class="back-link" @click="navigate('/masael')">← {{language==='bn'?'সব মাসায়েল':'All masael'}}</button><div class="detail-body masael-detail"><span class="public-tag">{{publicDetail.category||'Masael'}}</span><h1>{{publicDetail.title}}</h1><section v-if="publicDetail.question"><h2>{{language==='bn'?'প্রশ্ন':'Question'}}</h2><p>{{publicDetail.question}}</p></section><section v-if="publicDetail.short_answer" class="short-answer-box"><h2>{{language==='bn'?'সংক্ষিপ্ত উত্তর':'Short answer'}}</h2><p>{{publicDetail.short_answer}}</p></section><section v-if="publicDetail.answer"><h2>{{language==='bn'?'বিস্তারিত উত্তর':'Detailed answer'}}</h2><p>{{publicDetail.answer}}</p></section><section v-if="publicDetail.references"><h2>{{language==='bn'?'সূত্র':'References'}}</h2><p>{{publicDetail.references}}</p></section><aside class="source-disclaimer">{{language==='bn'?'এটি সাধারণ তথ্য; ব্যক্তিগত ধর্মীয় পরামর্শের জন্য যোগ্য আলেমের সঙ্গে কথা বলুন।':'For personal religious guidance, consult a qualified scholar.'}}</aside></div></div><div v-else class="public-empty">{{language==='bn'?'উত্তর লোড হচ্ছে…':'Loading answer…'}}</div></section>
<section v-else-if="path==='/resources'" class="public-listing"><div class="public-title-row"><div><span class="public-kicker muted">{{language==='bn'?'পড়া, দেখা ও শোনা':'READ · WATCH · LISTEN'}}</span><h1>{{language==='bn'?'ইসলামি পাঠাগার':'Islamic resource shelf'}}</h1><p>{{language==='bn'?'বই, জার্নাল, প্রবন্ধ, ভিডিও ও আলেমদের আলোচনা।':'Books, journals, papers, videos and scholar lectures shared by the administrator.'}}</p></div></div><div v-if="resources.length" class="resource-list-grid"><article v-for="item in resources" :key="item.id" class="resource-list-card"><div v-if="item.cover_url" class="resource-list-cover" :style="{backgroundImage:`url(${item.cover_url})`}"></div><span class="resource-type-pill">{{resourceTypeName(item.resource_type)}}</span><small>{{item.creator}}</small><h3>{{item.title}}</h3><p>{{item.summary}}</p><div class="resource-card-actions"><a :href="item.url" target="_blank" rel="noopener">{{language==='bn'?'মূল সূত্র খুলুন':'Open source'}} <ArrowUpRight :size="14"/></a><button v-if="item.slug" @click="navigate('/resources/'+item.slug)">{{language==='bn'?'বিবরণ':'Details'}}</button></div></article></div><div v-else class="public-empty">{{language==='bn'?'অ্যাডমিন সূত্র যোগ করলে এখানে বই, ভিডিও ও প্রবন্ধ দেখা যাবে।':'The administrator’s books, videos, papers and links will appear here.'}}</div></section>
<section v-else-if="path.startsWith('/resources/')" class="public-listing detail-page"><div v-if="publicDetail" class="long-content"><button class="back-link" @click="navigate('/resources')">← {{language==='bn'?'সব সূত্র':'All resources'}}</button><div class="detail-body"><span class="resource-type-pill">{{resourceTypeName(publicDetail.resource_type)}}</span><h1>{{publicDetail.title}}</h1><p v-if="publicDetail.creator" class="resource-creator">{{publicDetail.creator}}</p><p>{{publicDetail.summary}}</p><a class="public-primary" :href="publicDetail.url" target="_blank" rel="noopener">{{language==='bn'?'মূল সূত্র খুলুন':'Open the original source'}} <ArrowUpRight :size="16"/></a></div></div><div v-else class="public-empty">{{language==='bn'?'সূত্র লোড হচ্ছে…':'Loading resource…'}}</div></section>
<section v-else class="public-listing"><h1>{{t('notFound')}}</h1><button class="public-primary" @click="navigate('/')">{{t('backHome')}}</button></section>
<section v-if="path==='/' && notes.length" class="public-note-preview"><div><span class="public-kicker muted">{{t('thoughtKicker')}}</span><h2>From the notes</h2></div><article v-for="n in notes.slice(0,2)" :key="n.id"><span class="public-note-date">{{new Date(n.created_at).toLocaleDateString('en',{month:'long',day:'numeric'})}}</span><b>{{n.title}}</b><p>{{n.body?.slice(0,180)}}</p></article><button class="public-more" @click="navigate('/notes')">{{t('moreReflections')}} <ArrowUpRight :size="15"/></button></section></main><div v-else-if="loading" class="public-loading">Gathering a few good words…</div><footer class="public-footer"><a class="public-brand" href="/" @click.prevent="navigate('/')"><span class="public-brand-mark"><Flower2 :size="18"/></span><span>noor<span class="brand-period">.</span></span></a><span>{{t('footer')}}</span><a href="/admin">Admin sign in <ArrowUpRight :size="13"/></a></footer></div></template>
